NSDictionary *DRRideTool(void){return @{@"type":@"function",@"function":@{@"name":@"didi_ride",@"description":@"滴滴出行沙箱（非真实订单）。用户要打车时调用。search(city,query)搜索地点并返回可选id；estimate(from_id,to_id)用已经选定的地点预估；prepare(product_id)显示车型价格并等待眼镜旋钮确认；status查询；prepare_cancel显示取消确认。不得自行确认、不得说已叫到真实车。未指定起点/目的地时追问；地点不唯一让用户选择；坐标/车型/订单ID只能来自本工具。一次只调用一个工具。",@"parameters":@{@"type":@"object",@"properties":@{@"action":@{@"type":@"string",@"enum":@[@"search",@"estimate",@"prepare",@"status",@"prepare_cancel"]},@"city":@{@"type":@"string"},@"query":@{@"type":@"string"},@"from_id":@{@"type":@"string"},@"to_id":@{@"type":@"string"},@"product_id":@{@"type":@"string"}},@"required":@[@"action"],@"additionalProperties":@NO}}};}
NSDictionary *DRRideArguments(NSString *raw){if(![raw isKindOfClass:NSString.class]||raw.length>2000)return nil;id j=[NSJSONSerialization JSONObjectWithData:[raw dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil];if(![j isKindOfClass:NSDictionary.class])return nil;NSDictionary *spec=@{@"search":@[@"city",@"query"],@"estimate":@[@"from_id",@"to_id"],@"prepare":@[@"product_id"],@"status":@[],@"prepare_cancel":@[]};NSArray *keys=[j[@"action"]isKindOfClass:NSString.class]?spec[j[@"action"]]:nil;if(!keys||[j count]!=keys.count+1)return nil;for(NSString *k in keys){id v=j[k];if(![v isKindOfClass:NSString.class]||![v length]||[v length]>120||[v rangeOfCharacterFromSet:NSCharacterSet.controlCharacterSet].location!=NSNotFound)return nil;}return j;}
